const payload = $json.body || $json;
const event = payload.event || payload;
const resource = event.resource || {};
const rawEvent = event.raw?.event || event.raw || {};

let record_id = resource.record_id || payload.record_id || '';
// 兼容 listener 包装
if (!record_id && rawEvent.action_list?.[0]?.record_id) {
  record_id = rawEvent.action_list[0].record_id;
}

if (!record_id) {
  throw new Error('缺少 record_id：请确认 listener 推送订单表记录变更');
}

return [{ json: { record_id } }];

/**
 * 判定生成方式（读取订单记录 → 判定生成方式）
 *
 * 生成方式读自「报价生成状态」：附件生成 / 按需生成
 * 按需校验只看「客户需求」文案解析结果（不读订单表结构化字段）
 * 附件：不校验
 *
 * 错误码：缺生成方式 | 缺人数 | 缺出发地 | 缺目的地 | 缺出发日期 | 缺活动天数
 *
 * 同步：node scripts/sync_detect_quote_generate_mode.js
 */

function selectFieldText(field) {
  if (field == null) return '';
  if (typeof field === 'string') return field.trim();
  if (typeof field === 'number') return String(field);
  if (Array.isArray(field)) {
    return field
      .map((x) => selectFieldText(x))
      .filter(Boolean)
      .join('');
  }
  if (typeof field === 'object') {
    if (typeof field.text === 'string' && field.text.trim()) return field.text.trim();
    if (typeof field.name === 'string' && field.name.trim()) return field.name.trim();
    if (Array.isArray(field.value) && field.value.length) {
      return selectFieldText(field.value);
    }
  }
  return '';
}

/** 从客户需求文案取「标签：值」（行首标签；值可为空） */
function pickFromRequirement(text, labels) {
  const lines = String(text || '').split(/\r?\n/);
  for (const label of labels) {
    const re = new RegExp('^\\s*' + label + '\\s*[：:]\\s*(.*)$');
    for (const line of lines) {
      const m = line.match(re);
      if (m) return String(m[1] || '').trim();
    }
  }
  return '';
}

function parsePeople(raw) {
  if (raw == null || raw === '') return NaN;
  const m = String(raw).replace(/,/g, '').match(/(\d+(?:\.\d+)?)/);
  return m ? Number(m[1]) : NaN;
}

const recordId = $('解析触发记录').first().json.record_id;
const token = $('获取飞书Token').first().json.tenant_access_token || '';
const resp = $input.first().json;
const data = resp.data || resp;
const record = data.record || data;
const fields = record.fields || {};

// —— 生成方式 =「报价生成状态」——
const modeText = selectFieldText(fields['报价生成状态']);
let generate_mode = '';
if (modeText.includes('按需')) generate_mode = 'ondemand';
else if (modeText.includes('附件')) generate_mode = 'attachment';

const 订单号 =
  selectFieldText(fields['订单号']) ||
  selectFieldText(fields['订单编号']) ||
  recordId;
const 客户需求 = selectFieldText(fields['客户需求']);

// —— 仅从客户需求解析业务字段 ——
const 出发地 = pickFromRequirement(客户需求, ['出发地']);
const 目的地 = pickFromRequirement(客户需求, ['目的地']);
const 活动日期 = pickFromRequirement(客户需求, [
  '活动日期',
  '出发日期',
  '执行日期',
]);
const 活动天数 = pickFromRequirement(客户需求, ['活动天数', '天数']);
const 报价人数Raw = pickFromRequirement(客户需求, [
  '人数',
  '报价人数',
  '执行人数',
]);
const 报价人数Num = parsePeople(报价人数Raw);
const 报价人数 =
  Number.isFinite(报价人数Num) && 报价人数Num > 0 ? 报价人数Num : 报价人数Raw;

const errorCodes = [];
if (!generate_mode) errorCodes.push('缺生成方式');

if (generate_mode === 'ondemand') {
  if (!Number.isFinite(报价人数Num) || 报价人数Num <= 0) errorCodes.push('缺人数');
  if (!出发地) errorCodes.push('缺出发地');
  if (!目的地) errorCodes.push('缺目的地');
  if (!活动日期) errorCodes.push('缺出发日期');
  if (!活动天数) errorCodes.push('缺活动天数');
}

const validation_ok = errorCodes.length === 0;
const error_code = validation_ok ? '' : errorCodes[0];

return [
  {
    json: {
      validation_ok,
      error_code,
      error_codes: errorCodes,

      record_id: record.record_id || recordId,
      tenant_access_token: token,

      订单号,
      generate_mode,
      is_attachment: generate_mode === 'attachment',
      is_ondemand: generate_mode === 'ondemand',
      mode_text: modeText,
      客户需求,
      活动名称: selectFieldText(fields['活动名称']),
      报价人数,
      活动天数,
      活动日期,
      出发地,
      目的地,
      出发地目的地: [出发地, 目的地].filter(Boolean).join('-'),
      fields,
    },
  },
];

const base = $input.first().json;
if (base.generate_mode !== 'ondemand') {
  throw new Error('内部错误：按需分支收到非 ondemand');
}
if (!String(base.客户需求 || '').trim()) {
  throw new Error('按需生成要求填写「客户需求」');
}

const userPrompt = [
  '【订单已知字段】',
  '订单号：' + (base.订单号 || ''),
  '活动名称：' + (base.活动名称 || ''),
  '报价人数：' + (base.报价人数 || ''),
  '活动天数：' + (base.活动天数 || ''),
  '活动日期：' + (base.活动日期 || ''),
  '出发地目的地：' + (base.出发地目的地 || ''),
  '',
  '【客户需求】',
  base.客户需求,
  '',
  '请按系统要求只输出一个 JSON 对象。',
].join('\n');

return [{
  json: {
    ...base,
    user_prompt: userPrompt,
  },
}];

const base = $('组装按需上下文').first().json;
const raw = $json.output ?? $json.text ?? $json.response ?? '';

function extractJson(text) {
  const cleaned = String(text || '').replace(/```json/gi, '').replace(/```/g, '').trim();
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  if (start < 0 || end <= start) {
    throw new Error('AI 未返回 JSON 对象');
  }
  return JSON.parse(cleaned.slice(start, end + 1));
}

let data;
try {
  data = extractJson(raw);
} catch (e) {
  throw new Error('解析按需生成 AI 结果失败: ' + (e.message || e) + '\n原始输出: ' + String(raw).slice(0, 500));
}

const sheet_rows = Array.isArray(data.sheet_rows) ? data.sheet_rows : [];
const itinerary_rows = Array.isArray(data.itinerary_rows) ? data.itinerary_rows : [];

const normalizedSheet = sheet_rows
  .filter((r) => r && typeof r === 'object')
  .map((r) => ({
    类目: String(r.类目 || r.分类 || '其他'),
    物品名称: String(r.物品名称 || r.名称 || ''),
    描述: String(r.描述 || r.内容 || ''),
    数量: r.数量 == null || r.数量 === '' ? null : Number(r.数量),
    单价: null, // 价目由策划人工填写
  }))
  .filter((r) => r.物品名称 || r.描述);

const normalizedItinerary = itinerary_rows
  .filter((r) => r && typeof r === 'object')
  .map((r) => ({
    日期: String(r.日期 || r.date || ''),
    时间: String(r.时间 || r.time || ''),
    内容: String(r.内容 || r.content || r.描述 || ''),
  }))
  .filter((r) => r.日期 || r.时间 || r.内容);

return [{
  json: {
    record_id: base.record_id,
    订单号: base.订单号,
    generate_mode: 'ondemand',
    活动名称: data.活动名称 || base.活动名称 || '',
    报价人数: data.报价人数 ?? base.报价人数 ?? '',
    活动天数: data.活动天数 || base.活动天数 || '',
    活动日期: data.活动日期 || base.活动日期 || '',
    出发地目的地: data.出发地目的地 || base.出发地目的地 || '',
    税费及服务: (data.税费及服务 && String(data.税费及服务).trim()) || '5%',
    sheet_rows: normalizedSheet,
    itinerary_rows: normalizedItinerary,
    报价明细条目: normalizedSheet,
    行程明细: normalizedItinerary,
  },
}];

const recordId = $('解析触发记录').first().json.record_id;
const resp = $('读取订单记录').first().json;
const data = resp.data || resp;
const record = data.record || data;
const fields = record.fields || {};
const attachments = fields['报价单'] || [];
if (!Array.isArray(attachments) || attachments.length === 0) {
  throw new Error('订单无「报价单」附件');
}
const att = attachments[0];
const 订单号 = (() => {
  const v = fields['订单号'] ?? fields['订单编号'];
  if (v == null) return recordId;
  if (typeof v === 'string' || typeof v === 'number') return String(v);
  if (Array.isArray(v)) return String(v[0]?.text || v[0] || recordId);
  if (typeof v === 'object' && v.text != null) return String(v.text);
  return recordId;
})();

return [{
  json: {
    record_id: record.record_id || recordId,
    订单号,
    fields,
    报价单: attachments,
    tmp_url: att.tmp_url || '',
    file_token: att.file_token || att.token || '',
  },
}];

/**
 * 报价附件表格识别（Extract from File → 报价信息提取）
 *
 * 约定：
 * 1. 用「键最多且 ≥6」的行确定源列 key 顺序（最多 7 列 A–G），再映射全部行
 *    —— 避免用表头稀疏行（缺「趣加团建」类目列）定序导致总价行对不上
 * 2. 动态识别明细表头并映射列角色（含「网络价格」等中间列）
 * 3. 任一字格含「活动总价」，且同行其它格恰有一个数字 → 明细结束
 * 4. 表头上方用 A 标签 + 其后首个非空列取值提取活动名称/人数/天数/日期
 *
 * 同步到 n8n：复制本文件全文到「报价信息提取」Code 节点
 * （或改完后跑：node scripts/sync_quote_attachment_extract.js）
 */

// 上游：Extract from File 的全部行
const rawRows = $input.all().map((i) => i.json);

const MAX_COLS = 7;
const COLS = ['A', 'B', 'C', 'D', 'E', 'F', 'G'].slice(0, MAX_COLS);

/** 读单元格；空 → '' */
function cell(row, key) {
  const v = row?.[key];
  if (v == null || v === '') return '';
  return String(v).trim();
}

/** 转数字；非法 → null */
function num(v) {
  if (v == null || v === '') return null;
  if (typeof v === 'number' && Number.isFinite(v)) return v;
  const s = String(v).trim().replace(/,/g, '');
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
}

/** 只保留中文（类目清洗：去掉编号、英文、符号） */
function stripToChinese(raw) {
  return String(raw || '')
    .replace(/[^\u4e00-\u9fff]/g, '')
    .trim();
}

/** 税费/服务费类目：不进明细，抽百分比 */
function isTaxCategory(cat) {
  return /税费|服务费/.test(String(cat || ''));
}

/**
 * 解析百分比 → { display, ratio } | null
 */
function parsePercent(raw) {
  if (raw == null || raw === '') return null;

  if (typeof raw === 'string') {
    const s = raw.trim().replace(/％/g, '%');
    const m = s.match(/^(\d+(?:\.\d+)?)\s*%$/);
    if (m) {
      const pct = Number(m[1]);
      return { display: `${pct}%`, ratio: pct / 100 };
    }
    const n = Number(s);
    if (!Number.isFinite(n)) return null;
    raw = n;
  }

  if (typeof raw !== 'number' || !Number.isFinite(raw) || raw <= 0) return null;
  if (raw > 0 && raw <= 1) {
    const pct = Math.round(raw * 10000) / 100;
    return { display: `${pct}%`, ratio: raw };
  }
  if (raw <= 100) {
    return { display: `${raw}%`, ratio: raw / 100 };
  }
  return null;
}

/** 从 A–G 找第一个百分比 */
function extractPercentFromRow(row) {
  for (const k of COLS) {
    const parsed = parsePercent(row?.[k]);
    if (parsed) return parsed;
  }
  return null;
}

/** Excel 序列号 / 文本 → 中文日期 */
function fmtCnDate(raw) {
  if (raw == null || raw === '') return '';

  const n = typeof raw === 'number' ? raw : Number(String(raw).trim());
  if (Number.isFinite(n) && n > 20000 && n < 80000 && !/[\/\-年]/.test(String(raw))) {
    const d = new Date(Date.UTC(1899, 11, 30) + Math.floor(n) * 86400000);
    return `${d.getUTCFullYear()}年${d.getUTCMonth() + 1}月${d.getUTCDate()}日`;
  }

  const s = String(raw).trim();
  if (/年/.test(s)) return s;
  const m = s.match(/(\d{4})[\/\-年](\d{1,2})[\/\-月]?(\d{1,2})?/);
  if (m) return `${m[1]}年${Number(m[2])}月${Number(m[3] || 1)}日`;
  return s;
}

/**
 * 选「键最多」的行定 A–G 源键（至少 6 个）。
 * 表头行常缺类目列（趣加团建），满键明细行才含完整物理列序。
 */
function detectSourceKeys(inputRows) {
  let best = null;
  let bestLen = 0;
  for (const row of inputRows) {
    if (!row || typeof row !== 'object') continue;
    const keys = Object.keys(row);
    if (keys.length >= 6 && keys.length > bestLen) {
      best = keys;
      bestLen = keys.length;
    }
  }
  if (!best) {
    throw new Error(
      '未找到含完整 6 个键的行，无法确定列顺序（请确认 Extract from File 输出）',
    );
  }
  return best.slice(0, MAX_COLS);
}

/**
 * 将 Extract 行归一化为 { A,B,C,... }
 * sourceKeys：全表统一的原始字段名
 */
function normalizeRows(inputRows, sourceKeys) {
  return inputRows.map((row) => {
    const out = {};
    for (const k of COLS) out[k] = '';
    const src = row && typeof row === 'object' ? row : {};
    for (let i = 0; i < sourceKeys.length && i < COLS.length; i++) {
      const k = sourceKeys[i];
      out[COLS[i]] = k != null && k in src ? src[k] : '';
    }
    return out;
  });
}

function rowTexts(row) {
  return COLS.map((k) => cell(row, k));
}

function rowBlob(row) {
  return rowTexts(row).filter(Boolean).join(' ');
}

/**
 * 明细表头：同一行需同时出现 物品名称、描述、数量、单价
 * 返回 { index, colMap }
 */
function detectDetailHeader(rows) {
  const idx = rows.findIndex((r) => {
    const blob = rowBlob(r);
    return (
      blob.includes('物品名称') &&
      blob.includes('描述') &&
      blob.includes('数量') &&
      blob.includes('单价')
    );
  });
  if (idx < 0) {
    throw new Error('未找到明细表头行（需含：物品名称、描述、数量、单价）');
  }

  const header = rows[idx];
  const colMap = {
    categoryCol: null,
    nameCol: null,
    descCol: null,
    qtyCol: null,
    priceCol: null,
    totalCol: null,
  };

  for (const k of COLS) {
    const t = cell(header, k);
    if (!t) continue;
    if (t.includes('类目') || t.includes('分类')) colMap.categoryCol = k;
    if (t.includes('物品名称') || t === '名称') colMap.nameCol = k;
    if (t.includes('描述') || t.includes('内容')) colMap.descCol = k;
    if (t.includes('数量')) colMap.qtyCol = k;
    if (t.includes('单价')) colMap.priceCol = k;
    if (t.includes('总价') || t.includes('小计') || t.includes('金额')) colMap.totalCol = k;
  }

  // 表头 A 为空 → 默认 A 为类目列
  if (!colMap.categoryCol && !cell(header, 'A')) {
    colMap.categoryCol = 'A';
  }
  if (!colMap.categoryCol) colMap.categoryCol = 'A';
  if (!colMap.nameCol) colMap.nameCol = 'B';
  if (!colMap.descCol) colMap.descCol = 'C';
  if (!colMap.qtyCol) colMap.qtyCol = 'D';
  if (!colMap.priceCol) colMap.priceCol = 'E';
  if (!colMap.totalCol) colMap.totalCol = 'F';

  return { index: idx, colMap };
}

/**
 * 活动总价行：任一字格文本含「活动总价」，且其余格恰有一个可解析数字
 * （兼容总价写在数量/单价列，如 __EMPTY_2=79800）
 */
function findActivityTotalIndex(rows, afterIdx) {
  for (let i = afterIdx + 1; i < rows.length; i++) {
    const r = rows[i];
    let labelCol = null;
    for (const k of COLS) {
      if (cell(r, k).includes('活动总价')) {
        labelCol = k;
        break;
      }
    }
    if (!labelCol) continue;

    let numericCount = 0;
    for (const k of COLS) {
      if (k === labelCol) continue;
      const raw = r[k];
      if (raw == null || raw === '') continue;
      if (num(raw) != null) numericCount += 1;
    }
    if (numericCount === 1) return i;
  }
  return -1;
}

/** 标签行取值：A 为标签时，取 B→G 第一个非空 */
function firstValueAfterA(row) {
  for (const k of COLS) {
    if (k === 'A') continue;
    const raw = row[k];
    if (raw != null && raw !== '') return raw;
  }
  return '';
}

/**
 * 表头上方元数据：A 标签，其后首个非空列为值
 */
function extractMetaAbove(rows, headerIdx) {
  let 活动名称 = '';
  let 报价人数 = '';
  let 活动天数 = '';
  let 活动日期 = '';

  for (let i = 0; i < headerIdx; i++) {
    const r = rows[i];
    const a = cell(r, 'A');
    if (!a) continue;

    const label = a.replace(/\s*[:：]\s*$/, '').trim();
    const valueRaw = firstValueAfterA(r);
    const valueText =
      valueRaw == null || valueRaw === '' ? '' : String(valueRaw).trim();

    if (label === '活动日期' && !活动日期) {
      活动日期 = fmtCnDate(valueRaw);
      continue;
    }

    if (label.includes('人数') && 报价人数 === '') {
      const n = num(valueRaw);
      报价人数 = n != null ? n : valueText;
      continue;
    }

    if ((label === '活动天数' || label.includes('活动天数')) && !活动天数) {
      活动天数 = valueText;
      continue;
    }

    if (!活动名称) {
      if (label === '活动名称' || /名称$/.test(label)) {
        活动名称 = valueText;
      }
    }
  }

  return { 活动名称, 报价人数, 活动天数, 活动日期 };
}

// —— 主流程 ——
const sourceKeys = detectSourceKeys(rawRows);
const rows = normalizeRows(rawRows, sourceKeys);
const { index: headerIdx, colMap } = detectDetailHeader(rows);

const totalIdx = findActivityTotalIndex(rows, headerIdx);
if (totalIdx < 0) {
  throw new Error(
    '未找到「活动总价」行（要求任一字格含活动总价，且同行其余格恰有一个数字）',
  );
}

const { 活动名称, 报价人数, 活动天数, 活动日期 } = extractMetaAbove(rows, headerIdx);

const sheet_rows = [];
let lastCategory = '';
let lastItemName = '';
let 税费及服务 = '';
let taxRatio = null;

for (let i = headerIdx + 1; i < totalIdx; i++) {
  const r = rows[i];

  const catRaw = cell(r, colMap.categoryCol);
  const catZh = stripToChinese(catRaw);
  if (catZh) lastCategory = catZh;
  const 类目 = lastCategory || '费用';

  const name = cell(r, colMap.nameCol);
  const desc = cell(r, colMap.descCol)
    .replace(/[\r\n]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  const qtyRaw = r[colMap.qtyCol];
  const priceRaw = r[colMap.priceCol];

  // 税费类：不进明细，抽百分比
  if (isTaxCategory(类目)) {
    if (!税费及服务) {
      const parsed =
        extractPercentFromRow(r) ||
        parsePercent(priceRaw) ||
        parsePercent(qtyRaw) ||
        parsePercent(desc) ||
        parsePercent(catRaw);
      if (parsed) {
        税费及服务 = parsed.display;
        taxRatio = parsed.ratio;
      }
    }
    continue;
  }

  // 跳过表头残留
  if (name === '物品名称' || desc === '描述') continue;

  const qtyN = num(qtyRaw);
  const priceN = num(priceRaw);
  // 不因总价为 0 过滤：有物品名称 / 描述 / 单价任一即可进明细

  if (name) lastItemName = name;
  const itemName = name || lastItemName || '';

  // 仅类目行或完全空行：不产出明细
  if (!itemName && !desc && priceN == null) continue;

  sheet_rows.push({
    类目,
    物品名称: itemName || '(未命名)',
    描述: desc,
    数量: qtyN,
    单价: priceN,
  });
}

const order = $('读取订单记录').first().json.data.record;
const orderRecordId = order.record_id || '';
const orderNo = order.fields?.订单号 || orderRecordId;

return [
  {
    json: {
      record_id: orderRecordId,
      活动名称,
      报价人数,
      活动天数,
      活动日期,
      出发地目的地: '', // 本算法不匹配该占位符
      税费及服务,
      税费及服务比例: taxRatio,
      订单号: orderNo,
      sheet_rows,
      报价明细条目: sheet_rows,
    },
  },
];

const quote = $input.first().json;
const rows = $('Extract from File').all().map((i) => i.json);

function cell(row, key) {
  const v = row?.[key];
  if (v == null || v === '') return '';
  return String(v).trim();
}

/** Excel 时间小数 / 文本 → "HH:MM"；已含冒号则原样 */
function fmtTime(raw) {
  if (raw == null || raw === '') return '';

  if (typeof raw === 'string') {
    const s = raw.trim();
    if (!s) return '';
    // 已是时间或区间文案
    if (/:/.test(s) || /[点时]/.test(s)) return s;
    const n = Number(s);
    if (!Number.isFinite(n)) return s;
    raw = n;
  }

  if (typeof raw !== 'number' || !Number.isFinite(raw)) {
    return String(raw).trim();
  }

  // 0~1：纯时间；>=1：日期序列，只取小数部分
  let frac = raw;
  if (raw >= 1) frac = raw - Math.floor(raw);
  if (frac < 0 || frac >= 1) return String(raw);

  const totalMin = Math.round(frac * 24 * 60);
  const hh = Math.floor(totalMin / 60) % 24;
  const mm = totalMin % 60;
  return `${String(hh).padStart(2, '0')}:${String(mm).padStart(2, '0')}`;
}

function isEmptyCell(v) {
  return v == null || v === '';
}

const COL_A = 'QUJIA趣加团建';
const COL_TIME = '__EMPTY';
const COL_CONTENT = '__EMPTY_1';

const STOP_RE = /活动总价|税费及服务|费用明细|报价明细|结算/;

const sectionIdx = rows.findIndex((r) => cell(r, COL_A).includes('活动行程'));
const itinerary_rows = [];

if (sectionIdx >= 0) {
  let headerIdx = -1;
  for (let i = sectionIdx + 1; i < rows.length; i++) {
    const a = cell(rows[i], COL_A);
    if (a.includes('日期')) {
      headerIdx = i;
      break;
    }
    if (STOP_RE.test(a)) break;
  }

  if (headerIdx >= 0) {
    let lastDate = '';
    let blankStreak = 0;
    for (let i = headerIdx + 1; i < rows.length; i++) {
      const r = rows[i];
      const dateRaw = cell(r, COL_A);
      const timeRaw = r[COL_TIME];
      const time = fmtTime(timeRaw);
      const content = cell(r, COL_CONTENT)
        .replace(/[\r\n]+/g, ' ')
        .replace(/\s+/g, ' ')
        .trim();

      if (STOP_RE.test(dateRaw) || STOP_RE.test(content)) break;
      if (dateRaw === '日期' || time === '时间' || cell(r, COL_TIME) === '时间') continue;

      if (!dateRaw && isEmptyCell(timeRaw) && !content) {
        blankStreak += 1;
        if (blankStreak >= 2) break;
        continue;
      }
      blankStreak = 0;

      const date = dateRaw || lastDate;
      if (dateRaw) lastDate = dateRaw;
      if (!date && !time && !content) continue;
      if (!time && !content) continue;

      itinerary_rows.push({
        日期: date,
        时间: time,
        内容: content,
      });
    }
  }
}

return [{
  json: {
    ...quote,
    itinerary_rows,
    行程明细: itinerary_rows,
  },
}];

/**
 * 组装在线报价生成请求（报价提取 / 按需生成 → 组装生成请求）
 *
 * 职责：
 * 1. 从上游报价结果 + 订单记录拼装 /api/generate 请求体
 * 2. 按策划师 open_id 映射输出目录 folder_token
 * 3. 按生成方式校验；失败时输出短错误码（供 IF 分流后回写「报价生成状态」）
 *
 * 校验分流：
 *   - 附件生成：人数 + 策划师/输出目录
 *   - 按需生成：订单号/出发地/目的地/出发日期/活动天数 + 策划师/输出目录
 *   （缺策划师 / 缺输出目录：两种方式都校验）
 *
 * 同步：node scripts/sync_assemble_online_quote_request.js
 * 或手动粘贴到 n8n「组装生成请求」Code 节点
 */

const q = $input.first().json;
const token = $('获取飞书Token').first().json.tenant_access_token || '';

/** 策划师 open_id → 飞书云空间输出目录 folder_token */
const PLANNER_OUTPUT_FOLDER = {
  'ou_31f3068ea0ae6fa7ffb24afaa2715c2d': 'OvlefG0vnl8DVudsbgyc5CUpndb',
  'ou_20aacc78880fafd1e978064db74b8caa': 'BDTPfGghllN9HVd5CQacURbGnZe',
  // 继续加：'ou_xxx': 'folderTokenXxx',
};

const orderRecord = $('读取订单记录').first().json.data.record || {};
const orderFields = orderRecord.fields || {};
const recordId =
  q.record_id ||
  orderRecord.record_id ||
  $('解析触发记录').first().json.record_id ||
  '';

const plannerId =
  orderFields?.策划师?.[0]?.id ||
  orderFields?.策划师?.[0]?.open_id ||
  '';
const folder_token = PLANNER_OUTPUT_FOLDER[plannerId] || '';

/** 飞书多维表格字段 / 字符串清洗 */
function textOf(v) {
  if (v == null || v === '') return '';
  if (typeof v === 'string' || typeof v === 'number') return String(v).trim();
  if (Array.isArray(v)) {
    return v
      .map((x) => (x && (x.text ?? x.name ?? x)) || '')
      .map((s) => String(s).trim())
      .filter(Boolean)
      .join('');
  }
  if (typeof v === 'object' && v.text != null) return String(v.text).trim();
  return String(v).trim();
}

/** 生成方式：上游透传 → 判定生成方式节点 → 订单「报价生成状态」 */
function resolveGenerateMode() {
  const fromQ = q.generate_mode || (q.is_attachment ? 'attachment' : '') || (q.is_ondemand ? 'ondemand' : '');
  if (fromQ === 'attachment' || fromQ === 'ondemand') return fromQ;
  try {
    const d = $('判定生成方式').first().json || {};
    if (d.generate_mode === 'attachment' || d.generate_mode === 'ondemand') {
      return d.generate_mode;
    }
  } catch (_) {
    /* 节点未执行时忽略 */
  }
  const status = textOf(orderFields['报价生成状态']);
  if (status.includes('按需')) return 'ondemand';
  if (status.includes('附件')) return 'attachment';
  return '';
}

const generate_mode = resolveGenerateMode();

// —— 业务字段（优先报价提取 / 按需结果，回退订单表）——
const 订单号 =
  textOf(q.订单号) ||
  textOf(orderFields['订单号']) ||
  textOf(orderFields['订单编号']);

const 报价人数Raw = q.报价人数 ?? orderFields['报价人数'] ?? orderFields['执行人数'];
const 报价人数Num = Number(
  typeof 报价人数Raw === 'object' && 报价人数Raw != null
    ? 报价人数Raw.text ?? 报价人数Raw
    : 报价人数Raw,
);

const 活动天数 =
  textOf(q.活动天数) ||
  textOf(orderFields['活动天数']) ||
  textOf(orderFields['天数']);

let 出发地 = textOf(q.出发地) || textOf(orderFields['出发地']);
let 目的地 = textOf(q.目的地) || textOf(orderFields['目的地']);
const 出发地目的地 =
  textOf(q.出发地目的地) || textOf(orderFields['出发地目的地']);
// 「上海-舟山」一类合并字段拆成出发地 / 目的地
if ((!出发地 || !目的地) && 出发地目的地) {
  const parts = 出发地目的地
    .split(/[-—–～~]/)
    .map((s) => s.trim())
    .filter(Boolean);
  if (!出发地 && parts[0]) 出发地 = parts[0];
  if (!目的地 && parts[1]) 目的地 = parts[1];
}

const 出发日期 =
  textOf(q.活动日期) ||
  textOf(q.执行日期) ||
  textOf(q.出发日期) ||
  textOf(orderFields['执行日期']) ||
  textOf(orderFields['活动日期']);

// —— 校验：附件校人数；按需校业务字段；策划师/输出目录两种方式都校 ——
const errorCodes = [];
const isAttachment = generate_mode === 'attachment';
const isOndemand = generate_mode === 'ondemand';

if (isAttachment) {
  if (!Number.isFinite(报价人数Num) || 报价人数Num <= 0) errorCodes.push('缺人数');
} else if (isOndemand) {
  if (!订单号) errorCodes.push('缺订单号');
  if (!出发地) errorCodes.push('缺出发地');
  if (!目的地) errorCodes.push('缺目的地');
  if (!出发日期) errorCodes.push('缺出发日期');
  if (!活动天数) errorCodes.push('缺活动天数');
} else {
  // 方式未知时保守：两边业务规则都做
  if (!Number.isFinite(报价人数Num) || 报价人数Num <= 0) errorCodes.push('缺人数');
  if (!订单号) errorCodes.push('缺订单号');
  if (!出发地) errorCodes.push('缺出发地');
  if (!目的地) errorCodes.push('缺目的地');
  if (!出发日期) errorCodes.push('缺出发日期');
  if (!活动天数) errorCodes.push('缺活动天数');
}

if (!plannerId) errorCodes.push('缺策划师');
else if (!folder_token) errorCodes.push('缺输出目录');

const validation_ok = errorCodes.length === 0;
const error_code = validation_ok ? '' : errorCodes[0];

return [
  {
    json: {
      // IF 分流：true → 生成在线报价；false → HTTP 回写 error_code 到「报价生成状态」
      validation_ok,
      error_code,
      error_codes: errorCodes,
      generate_mode,

      record_id: recordId,
      tenant_access_token: token,
      signing_unit: '在线报价',
      folder_token,

      fields: {
        订单号: 订单号 || '',
        活动名称: q.活动名称 || '',
        报价人数:
          Number.isFinite(报价人数Num) && 报价人数Num > 0
            ? 报价人数Num
            : q.报价人数 ?? '',
        活动天数: 活动天数 || q.活动天数 || '',
        活动日期: 出发日期 || q.活动日期 || '',
        出发地,
        目的地,
        出发地目的地:
          出发地目的地 || [出发地, 目的地].filter(Boolean).join('-'),
        税费及服务: q.税费及服务 || '',
      },
      sheet_rows: q.sheet_rows || [],
      itinerary_rows: q.itinerary_rows || [],

      _meta: {
        record_id: recordId,
        策划师id: plannerId,
        folder_token,
        generate_mode,
        validation_ok,
        error_code,
        error_codes: errorCodes,
      },
    },
  },
];

const gen = $input.first().json;
const meta = $('组装生成请求').first().json._meta || {};
const recordId = meta.record_id || $('解析触发记录').first().json.record_id;
const token = $('获取飞书Token').first().json.tenant_access_token || '';
const ok = !!gen.success && !!gen.document_url;

const fields = ok
  ? {
      报价生成状态: '已生成',
      在线报价: {
        text: gen.document_name || '在线报价',
        link: gen.document_url,
      },
    }
  : {
      报价生成状态: '生成失败',
    };

return [{
  json: {
    record_id: recordId,
    tenant_access_token: token,
    fields,
    _gen: gen,
  },
}];
